from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
left = Motor(Port.C, Direction.COUNTERCLOCKWISE)
Right_ = Motor(Port.D, Direction.CLOCKWISE)
flower = DriveBase(left, Right_, 62.4, 114)
Back_Arm = Motor(Port.A, Direction.CLOCKWISE)
Front_arm = Motor(Port.E, Direction.CLOCKWISE)


# The main program starts here.
flower.straight(330)
flower.turn(45)
flower.straight(300)
flower.turn(45)
flower.straight(250)
flower.turn(65)
